/* ===== ÉLEVAGE TERRESTRE ===== */
const FR_=S=>S.lieu.startsWith("France");
const has=(w)=>S=>S.lieu.includes(w);

L("poulet",{nom:"Poulet de chair",cat:"terre",poids:74000,sprite:"poulet",sc:{bg:"hangar",n:60},
 lieux:["Brésil","Chine","États-Unis","France, Bretagne","Thaïlande","Pologne"],cond:"Élevage intensif, bâtiment fermé",
 nat:2900,natTxt:"Un poulet peut vivre de 5 à 8 ans.",
 note:"Les poulets de chair représentent la très grande majorité des animaux terrestres abattus chaque année dans le monde : plus de 70 milliards.",
 ev:[
 {d:1,sc:{who:"poussin",n:45},pl:"poussin",x:"Tu sors de l'œuf dans un incubateur, au milieu de dizaines de milliers d'autres. Tu ne verras jamais ta mère. Un camion vous dépose dans un grand bâtiment fermé, sur une litière de copeaux.",
  e:"Une hirondelle entrée par une trappe d'aération se pose sur une poutre : « Dehors, il y a un ciel. Ici, il y a des néons. »",
  f:"Un bâtiment standard de poulets de chair en France compte souvent entre 20 000 et 40 000 oiseaux.",
  c:[{l:"Te serrer contre les autres",r:"Il fait chaud au milieu du groupe. Tu t'endors.",p:-1},{l:"Explorer le bâtiment",r:"Il n'y a pas de fin visible. Des lampes, des abreuvoirs, des mangeoires. Et le bruit.",p:1}]},
 {d:6,sc:{who:"poussin",n:50},pl:"poussin",x:"La lumière reste allumée presque tout le temps. Plus tu restes éveillé, plus tu manges.",
  e:"Un enfant en visite, le nez collé à la vitre : « Ils dorment jamais ? »",
  f:"La directive européenne de 2007 impose au moins 6 heures d'obscurité par jour, dont 4 heures sans interruption.",
  c:[{l:"Aller à la mangeoire",r:"Tu manges. Puis tu y retournes."},{l:"Chercher un coin sombre",r:"Il n'y en a pas.",p:1}]},
 {d:12,sc:{n:35},x:"Tes plumes blanches remplacent le duvet. Ton corps prend de l'avance sur tes os.",
  e:"Une poule de basse-cour, dans le jardin d'à côté : « À ton âge, j'étais légère comme une plume. »",
  f:"Selon une étude de 2014 (Zuidhof et al.), un poulet de chair moderne grossit environ cinq fois plus vite qu'une souche de 1957, nourrie avec le même aliment.",
  c:[{l:"Manger encore",r:"Tu prends du poids. C'est ce qu'on attend de toi.",s:-1},{l:"Te reposer près du mur",r:"Tu dors beaucoup. Ton corps est lourd pour ton âge."}]},
 {d:18,sc:{n:40},x:"Un autre poulet gratte la litière à côté de toi. Gratter, picorer, prendre un bain de poussière : ce sont les gestes de ton espèce. La litière est déjà tassée.",
  e:"Un coq sauvage de la jungle d'Asie, ton lointain ancêtre, s'il pouvait te voir : « On grattait la terre douze heures par jour. »",
  f:"Le bain de poussière est un besoin si fort chez les gallinacés que, privés de substrat, ils le miment « à vide ».",
  c:[{l:"Gratter avec lui",r:"Vous grattez côte à côte. Pendant un moment, tu fais ce qu'un poulet fait.",p:-1},{l:"Prendre un bain de poussière",r:"La litière est trop humide. Tu essaies quand même.",s:-1}]},
 {d:24,sc:{n:60},x:"Le sol a disparu. Il y a des corps partout, serrés les uns contre les autres. Pour boire, il faut traverser.",
  e:"Un inspecteur de passage, un carnet à la main : « Densité conforme. »",
  f:"L'Union européenne autorise jusqu'à 42 kg de poulets vivants par mètre carré, sous conditions. Cela représente environ 20 poulets adultes sur un mètre carré.",
  c:[{l:"Pousser jusqu'à l'abreuvoir",r:"Tu bois. Un autre poulet t'a piétiné au passage.",s:-1,p:1},{l:"Attendre qu'un passage s'ouvre",r:"Le passage ne s'ouvre pas. Tu finis par boire, beaucoup plus tard.",p:1},{l:"Rester couché",r:"La litière est humide sous toi. Ta peau s'irrite à son contact.",s:-1}]},
 {alt:[
  {d:30,sc:{n:70},x:"Tes pattes ont du mal à te porter. Chaque pas te coûte. Autour de toi, beaucoup d'autres boitent aussi.",
   e:"Une vétérinaire, à la radio dans la voiture de l'éleveur : « Les boiteries, c'est le problème numéro un en volaille. »",
   f:"L'EFSA, l'autorité européenne de sécurité des aliments, classe les troubles de la locomotion parmi les principaux problèmes de bien-être des poulets à croissance rapide.",
   c:[{l:"Te lever quand même",r:"Tu fais trois pas et tu te couches près de la mangeoire.",s:-1},{l:"Rester assis",r:"Tu restes assis. L'abreuvoir est à deux mètres.",s:-2}]},
  {d:30,sc:{n:70,heat:1},x:"Dehors, c'est la canicule. Dans le bâtiment, l'air chaud ne circule plus. L'odeur d'ammoniac pique les yeux.",
   e:"Le présentateur météo, sur la radio de l'éleveur : « Vigilance orange canicule sur tout l'Ouest. »",
   f:"Lors des épisodes de forte chaleur, des élevages de volailles peuvent perdre des milliers d'oiseaux en quelques heures si la ventilation tombe en panne.",
   c:[{l:"Ouvrir les ailes pour te refroidir",r:"Tu halètes, bec ouvert, ailes écartées. Comme tous les autres.",s:-1},{l:"Ne plus bouger",r:"Tu économises tes forces. Autour de toi, certains ne se relèvent pas.",p:2,risk:{p:.12,t:"La chaleur monte encore. Ton cœur lâche avant le soir."}}]}]},
 {d:36,sc:{n:75,extra:"eleveur"},x:"Un humain passe dans l'allée, comme chaque matin. Il ramasse ceux qui sont morts dans la nuit. Il a des dizaines de milliers de poulets à surveiller, et peu de temps.",
  e:"L'éleveur, à voix basse, sans te regarder : « Encore six jours. »",
  f:"La mortalité moyenne d'un lot de poulets standard se situe autour de 3 à 5 %. Sur 30 000 oiseaux, cela fait 1 000 à 1 500 morts.",
  c:[{l:"Te lever à son passage",r:"Il ne te regarde pas. Il n'a pas le temps de regarder."},{l:"Rester immobile",r:"Il s'arrête une seconde et te pousse du pied. Tu bouges. Il repart.",p:1}]},
 {d:42,end:1,sc:{bg:"camion",n:14,who:"poulet",still:1},x:"Cette nuit, la lumière baisse. Des équipes entrent dans le bâtiment. Des mains t'attrapent par les pattes et te placent dans une caisse, avec d'autres. Le camion démarre.",
  e:"Le chauffeur du camion, en fumant : « Le prochain lot arrive dans deux semaines. »",
  f:"Le ramassage se fait souvent de nuit, quand la lumière faible calme les oiseaux. Un bâtiment peut être vidé en quelques heures."}
 ]});

L("poussin",{nom:"Poussin mâle",cat:"terre",poids:6500,sprite:"poussin",sc:{bg:"couvoir",n:22},
 lieux:["Inde","États-Unis","Brésil","Chine","Espagne","Mexique"],cond:"Couvoir industriel, lignée pondeuse",
 nat:2900,natTxt:"Un coq peut vivre de 5 à 8 ans.",
 note:"Les poussins mâles des lignées pondeuses ne pondent pas et grossissent trop lentement pour la viande. Dans la plupart des pays, ils sont éliminés à la naissance.",
 ev:[
 {d:.04,x:"Tu sors de l'œuf dans un couvoir. Un tapis roulant t'emmène, avec des milliers d'autres, jusqu'à une table où des opérateurs vous trient.",
  e:"Une opératrice du couvoir, qui en trie des milliers par heure : « Mâle. Femelle. Mâle. Mâle. »",
  f:"Chaque année, environ 7 milliards de poussins mâles sont éliminés dans le monde à la naissance.",
  c:[{l:"Piauler",r:"Des milliers d'autres piaulent. Personne ne t'entend en particulier."},{l:"Essayer de descendre du tapis",r:"Le bord est trop haut. Le tapis avance.",p:1}]},
 {d:.08,x:"Une opératrice te retourne, regarde ton sexe en une seconde et te pose sur un autre tapis. Tu es un mâle. Ta lignée a été sélectionnée pour pondre. Tu ne pondras jamais.",
  e:"Un œuf, dans un couvoir allemand, analysé avant d'éclore : « Moi, on a su avant. On ne m'a pas fait naître. »",
  f:"Depuis 2022, la France et l'Allemagne interdisent en principe l'élimination des poussins mâles. Les œufs sont sexés avant l'éclosion, avec des exceptions.",
  c:[{l:"Te serrer contre ton voisin",r:"Il est mâle, lui aussi.",p:-1},{l:"Piauler plus fort",r:"Le tapis avance."}]},
 {d:.1,end:1,sc:{dark:.35},x:"Le tapis t'emmène vers le fond de la salle. Tu as vécu quelques heures.",
  e:"Une poule pondeuse, ta sœur, quelque part sur l'autre tapis : elle ne saura jamais que tu as existé.",
  f:"Les méthodes autorisées sont le broyage instantané ou le gazage. Certains poussins servent ensuite de nourriture pour les reptiles et les rapaces des zoos."}
 ]});

L("pondeuse",{nom:"Poule pondeuse",cat:"terre",poids:7000,sprite:"poule",sc:{bg:"cage",n:9,who:"poule"},
 lieux:["Chine","Inde","États-Unis","Mexique","France, Bretagne","Brésil"],cond:"Élevage en cage",
 nat:2900,natTxt:"Une poule peut vivre de 5 à 8 ans.",
 note:"En Europe, les cages en batterie sont interdites depuis 2012, mais les cages « aménagées » restent autorisées. Dans le monde, la majorité des poules pondeuses vivent encore en cage.",
 ev:[
 {d:1,sc:{bg:"couvoir",n:20,who:"poussin"},pl:"poussin",x:"Tu sors de l'œuf dans un couvoir. Une opératrice te retourne et te pose sur le tapis de gauche. Tu es une femelle : tu vivras.",
  e:"Ton frère, sur le tapis d'à côté : « Bonne chance. »",
  f:"Pour chaque poule pondeuse qui naît, un frère naît aussi. La plupart sont éliminés le jour même.",
  c:[{l:"Piauler",r:"Ton frère piaule aussi. Le tapis vous sépare."},{l:"Te taire",r:"Le tapis avance."}]},
 {d:126,x:"Tu as grandi dans un bâtiment d'élevage. Aujourd'hui, on te transfère dans une cage, avec d'autres poules. Ce sera ton espace jusqu'à la fin.",
  e:"Un client, devant un rayon d'œufs : « Code 3… c'est quoi déjà, le code 3 ? »",
  f:"Le premier chiffre gravé sur un œuf indique le mode d'élevage : 0 bio, 1 plein air, 2 au sol, 3 en cage.",
  c:[{l:"Chercher un coin pour pondre",r:"Tu tournes, tu cherches. Il n'y a pas de vrai nid.",p:1},{l:"Te poser contre le grillage",r:"Le grillage marque tes pattes.",s:-1}]},
 {d:210,x:"Tu pondras presque un œuf par jour, près de 300 par an. Le calcium de tes coquilles est pris sur ton squelette.",
  e:"Une poule sauvage de la jungle de Thaïlande : « Moi, j'en pond une douzaine par an. Et je les couve. »",
  f:"La poule sauvage ancestrale pondait de 10 à 15 œufs par an. Les lignées modernes en pondent près de 300.",
  c:[{l:"Manger le plus possible",r:"Ça ne suffit pas tout à fait. Tes os s'affinent.",s:-1},{l:"Picorer le grillage",r:"Tu picores ce qu'il y a. Il n'y a que du métal.",p:1}]},
 {d:315,x:"Une voisine de cage te donne des coups de bec. Il n'y a nulle part où aller.",
  e:"Un soigneur, qui passe vite : « Elles se piquent quand elles s'ennuient. »",
  f:"Le picage est un comportement fréquent chez les poules qui manquent d'espace et de stimulation. C'est pour le limiter qu'on épointe souvent leur bec.",
  c:[{l:"Rendre les coups",r:"Elle recule. Toi aussi, tu as perdu des plumes.",s:-1},{l:"Baisser la tête",r:"Elle continue. Ton dos se dégarnit.",s:-1,p:1}]},
 {alt:[
  {d:364,x:"Ton aile se casse contre les barreaux pendant une bousculade. Tes os sont devenus fragiles.",
   e:"Une vétérinaire, à un colloque : « L'ostéoporose est l'un des grands problèmes des poules en fin de ponte. »",
   f:"Des études ont observé des fractures du bréchet chez une grande partie des poules pondeuses, tous systèmes d'élevage confondus.",
   c:[{l:"Ne plus bouger",r:"Tu restes dans le coin de la cage. On continue à ramasser tes œufs.",s:-2},{l:"Continuer comme avant",r:"Chaque mouvement fait mal.",s:-2,p:1}]},
  {d:364,x:"Un soir, la ventilation s'arrête. Il fait de plus en plus chaud dans la rangée.",
   e:"Un technicien, réveillé par l'alarme : « J'arrive, j'arrive. »",
   f:"Un site de pondeuses en cage peut abriter plusieurs centaines de milliers de poules. Une panne de ventilation y devient vite critique.",
   c:[{l:"Haleter",r:"Le courant revient au bout d'une heure. Ta voisine ne s'est pas réveillée.",p:2},{l:"Te coller au grillage",r:"Un filet d'air passe par là. Tu tiens.",s:-1}]}]},
 {d:420,x:"Tu as perdu beaucoup de plumes et ta ponte ralentit. Dans un élevage, une poule qui pond moins coûte plus qu'elle ne rapporte.",
  e:"Une association qui adopte les poules de réforme, sur un tract : « Sauvez une poule, adoptez-la. »",
  f:"Des associations proposent d'adopter des poules en fin de carrière. Elles peuvent vivre encore plusieurs années dans un jardin.",
  c:[{l:"Continuer à pondre",r:"Tu pondras jusqu'au bout.",s:-1},{l:"Te reposer",r:"Ton corps ralentit. Quelqu'un le note sur un registre.",luck:{p:.08,f:"adoptee",yes:"Quelques jours plus tard, une bénévole t'emporte dans un carton. Tu sens de l'herbe pour la première fois.",no:"Ton nom n'est pas sur la liste des adoptions."}}]},
 {d:525,when:S=>!S.f.adoptee,end:1,sc:{bg:"camion",n:14,who:"poule",still:1},x:"On vide le bâtiment. Toutes les poules partent en même temps, pour faire place à un nouveau lot.",
  e:"Un enfant, mangeant un nugget à la cantine, sans savoir d'où il vient.",
  f:"La viande des poules de réforme sert surtout aux plats transformés, aux soupes et à l'alimentation animale."},
 {d:1800,when:S=>S.f.adoptee,end:1,sc:{bg:"jardin",n:2,who:"poule"},x:"Tu as vécu près de quatre ans de plus dans un jardin. Tes plumes ont repoussé. Tu as pris des bains de poussière tous les jours.",
  e:"La bénévole qui t'a adoptée : « Elle ne pondait presque plus. Ce n'était pas la question. »",
  f:"Une poule de réforme adoptée vit en général de deux à cinq ans de plus."}
 ]});

L("caille",{nom:"Caille",cat:"terre",poids:1400,sprite:"caille",sc:{bg:"cage",n:14,who:"caille"},
 lieux:["Chine","Brésil","France, Vendée","Espagne","Japon"],cond:"Élevage en cage ou au sol",
 nat:1460,natTxt:"Une caille peut vivre 3 à 4 ans.",
 note:"Plus d'un milliard de cailles sont élevées chaque année dans le monde pour leur viande et leurs œufs.",
 ev:[
 {d:1,sc:{bg:"couvoir",n:30,who:"caille"},x:"Tu éclos parmi des milliers d'autres. Tu tiens dans une cuillère à soupe.",
  e:"Une caille des blés, sauvage, en migration au-dessus de l'Afrique : « Moi, je traverse le Sahara chaque année. »",
  f:"La caille des blés sauvage migre entre l'Europe et l'Afrique. La caille japonaise, domestiquée, est celle qu'on élève.",
  c:[{l:"Te blottir",r:"Il fait chaud sous la lampe.",p:-1},{l:"Courir",r:"Tu cours vite. Tu te cognes aux autres."}]},
 {d:14,x:"Quand tu as peur, tu sautes à la verticale, comme pour t'envoler. Le plafond de la cage est bas.",
  e:"Un éleveur à son voisin : « On met des filets souples au plafond, sinon elles se cassent la tête. »",
  f:"Les cailles effrayées s'envolent à la verticale. Dans les cages basses, elles se blessent souvent à la tête.",
  c:[{l:"Sauter quand une porte claque",r:"Tu te cognes. Tu as une petite plaie sur le crâne.",s:-1,p:1},{l:"Rester tapie",r:"Tu restes tapie dans un coin, le cœur rapide.",p:2}]},
 {d:28,x:"Tu as presque ta taille adulte. Ton cri résonne dans le bâtiment, au milieu de milliers d'autres.",
  e:"Un chef dans un restaurant étoilé : « Caille rôtie, raisins, jus court. »",
  f:"Une caille de chair est abattue vers 4 à 5 semaines. Plus de 80 % des cailles élevées dans le monde le sont en Chine.",
  c:[{l:"Chanter",r:"Tu chantes. Une autre te répond."},{l:"Picorer",r:"Il y a des granulés. Toujours les mêmes."}]},
 {d:35,end:1,sc:{bg:"camion",n:24,who:"caille",still:1},x:"On attrape toute la cage d'un coup.",
  e:"Un enfant devant une boîte d'œufs de caille : « Ils sont tout petits ! »",
  f:"Les œufs de caille sont produits par des femelles gardées environ un an. Les mâles de ces lignées sont souvent éliminés ou engraissés."}
 ]});

L("canard",{nom:"Canard",cat:"terre",poids:3200,sprite:"canard",sc:{bg:"hangar",n:30,who:"canard"},
 lieux:["France, Landes","France, Gers","France, Vendée","Chine","Vietnam","Chine"],cond:"Élevage",
 nat:3650,natTxt:"Un canard peut vivre une dizaine d'années.",
 note:"La Chine élève les deux tiers des canards du monde. La France produit à elle seule la majorité du foie gras mondial.",
 ev:[
 {d:1,when:S=>!FR_(S),sc:{bg:"couvoir",n:18,who:"canard"},x:"Tu sors de l'œuf dans un couvoir. Tu es un caneton parmi des milliers.",
  e:"Une cane sauvage, sur un étang : « Mes petits me suivent dès la première heure. Les tiens, qui suivent-ils ? »",
  f:"Les canetons s'attachent au premier être qu'ils voient bouger : c'est l'empreinte, décrite par Konrad Lorenz.",
  c:[{l:"Suivre le premier qui bouge",r:"C'est un autre caneton. Tu le suis partout."},{l:"Te blottir",r:"Tu te blottis contre un autre caneton.",p:-1}]},
 {d:1,when:FR_,sc:{bg:"couvoir",n:18,who:"canard"},x:"Tu sors de l'œuf dans un couvoir. Tu es un canard mulard, un croisement créé pour le foie gras. Tu ne pourras pas avoir de petits. Les femelles de ta portée ont été écartées : leur foie est moins recherché.",
  e:"Une cane sauvage, sur un étang : « Mes petits me suivent dès la première heure. Les tiens, qui suivent-ils ? »",
  f:"Le canard mulard est un hybride stérile de cane Pékin et de canard de Barbarie. En foie gras, on engraisse surtout les mâles.",
  c:[{l:"Suivre le premier qui bouge",r:"C'est un autre caneton. Tu le suis partout."},{l:"Te blottir",r:"Tu te blottis contre un autre caneton.",p:-1}]},
 {d:21,when:S=>!FR_(S),sc:{n:50,who:"canard"},x:"Tu vis dans un grand bâtiment avec des milliers d'autres. Il n'y a pas d'eau pour nager, seulement des pipettes pour boire. Un canard a besoin de plonger la tête dans l'eau pour se nettoyer les yeux et les narines.",
  e:"Un enfant qui jette du pain aux canards du parc : « Ils sont trop mignons quand ils plongent ! »",
  f:"Le Conseil de l'Europe recommande de donner aux canards l'accès à une eau où ils peuvent plonger la tête. Ce n'est pas obligatoire dans la plupart des pays.",
  c:[{l:"Tremper la tête dans l'abreuvoir",r:"La tête ne rentre pas.",p:1},{l:"Lisser tes plumes",r:"Tu lisses tes plumes avec ce que tu as."}]},
 {d:45,when:S=>!FR_(S),end:1,sc:{bg:"camion",n:14,who:"canard",still:1},x:"Le bâtiment s'ouvre en pleine nuit. On vous pousse vers des caisses.",
  e:"Un cuisinier à Pékin, qui laque un canard : « Il faut trois jours pour un bon canard laqué. »",
  f:"Un canard Pékin de chair est abattu vers 6 semaines."},
 {d:35,when:FR_,sc:{bg:"pre",n:16,who:"canard"},x:"On t'ouvre un parcours dehors. Tu découvres l'herbe, la pluie, une flaque.",
  e:"Un randonneur sur le chemin : « Regarde, des canards en liberté. C'est bien, ici. »",
  f:"Avant le gavage, les canards à foie gras passent souvent plusieurs semaines en plein air.",
  c:[{l:"Plonger la tête dans la flaque",r:"L'eau est froide. Tu recommences dix fois.",p:-2},{l:"Rester avec le groupe",r:"Le groupe bouge ensemble, comme une seule bête.",p:-1}]},
 {d:84,when:FR_,sc:{bg:"gavage"},x:"On te transfère dans une salle de gavage, dans une petite cage individuelle. Deux fois par jour, un tube descend dans ton gosier et dépose une ration de maïs.",
  e:"Un touriste britannique au marché de Sarlat : « C'est interdit de le produire chez nous. On l'achète quand même. »",
  f:"Le gavage est interdit dans plusieurs pays, dont le Royaume-Uni, l'Allemagne et l'Italie. L'importation y reste souvent autorisée. En France, le foie gras est protégé par la loi comme patrimoine culturel.",
  c:[{l:"Tendre le cou",r:"C'est plus rapide.",s:-1},{l:"Reculer",r:"Il n'y a pas de place pour reculer.",s:-1,p:2}]},
 {d:94,when:FR_,sc:{bg:"gavage"},x:"Ton foie a grossi jusqu'à près de dix fois sa taille normale. Tu respires vite. Tu bouges peu.",
  e:"Le gaveur, 30 ans de métier : « On les gave comme nos grands-pères. On en prend soin. »",
  f:"Le gavage dure environ 10 à 12 jours. Le foie d'un canard gavé pèse en moyenne 500 à 600 grammes.",
  c:[{l:"Haleter",r:"Tu halètes, bec ouvert.",s:-2},{l:"Rester immobile",r:"Tu attends la prochaine ration.",s:-1,p:1}]},
 {d:96,when:FR_,end:1,sc:{bg:"camion",n:14,who:"canard",still:1},x:"Le gavage est terminé. Ce matin, on vient chercher toute la salle.",
  e:"Une famille au réveillon de Noël, qui trinque.",
  f:"Environ 70 % du foie gras français est consommé pendant les fêtes de fin d'année."}
 ]});

L("oie",{nom:"Oie",cat:"terre",poids:700,sprite:"oie",sc:{bg:"pre",n:18,who:"oie"},
 lieux:["Chine","Hongrie","Pologne","Égypte","France, Périgord"],cond:"Élevage au pré",
 nat:7300,natTxt:"Une oie peut vivre plus de 20 ans.",
 note:"La Chine élève l'immense majorité des oies du monde. Leur duvet remplit couettes et doudounes.",
 ev:[
 {d:1,sc:{bg:"couvoir",n:14,who:"oie"},x:"Tu sors de l'œuf. Tu cherches ta mère. Il n'y a que des oisons et une lampe chauffante.",
  e:"Une oie cendrée, en vol vers le sud : « Nous, on reste en couple toute la vie. »",
  f:"Les oies forment des couples durables et vivent en familles très soudées.",
  c:[{l:"Siffler",r:"Les autres sifflent aussi."},{l:"Suivre le groupe",r:"Vous avancez ensemble.",p:-1}]},
 {d:60,x:"Tu vis au pré avec ta bande. Vous marchez en file. Tu montes la garde quand les autres mangent.",
  e:"Un facteur, qui recule devant la bande : « Mieux qu'un chien de garde. »",
  f:"Les oies sont d'excellentes sentinelles. Selon la légende, celles du Capitole ont sauvé Rome d'une attaque.",
  c:[{l:"Monter la garde",r:"Tu cries dès qu'un inconnu approche.",p:1},{l:"Brouter",r:"L'herbe est grasse.",p:-1}]},
 {d:90,when:S=>!has("France")(S),x:"Ton duvet a poussé. Des mains t'attrapent. On arrache des plumes sur ton ventre.",
  e:"Une cliente qui choisit une doudoune : « Duvet d'oie, c'est le plus chaud. »",
  f:"Le plumage à vif est interdit dans l'Union européenne. La récolte pendant la mue naturelle est tolérée, et des enquêtes ont montré des abus en Europe de l'Est et en Chine.",
  c:[{l:"Te débattre",r:"On te tient plus fort.",s:-1,p:2},{l:"Te figer",r:"Ça dure quelques minutes.",s:-1,p:1}]},
 {d:150,end:1,sc:{bg:"camion",n:12,who:"oie",still:1},x:"La bande est chargée dans un camion. Ensemble, comme toujours.",
  e:"Un enfant devant un livre d'images : « O comme oie. »",
  f:"Une oie de chair est en général abattue entre 4 et 6 mois."}
 ]});

L("dinde",{nom:"Dinde",cat:"terre",poids:600,sprite:"dinde",sc:{bg:"hangar",n:28,who:"dinde"},
 lieux:["États-Unis","Brésil","France, Bretagne","Pologne","Allemagne"],cond:"Élevage intensif, bâtiment",
 nat:3650,natTxt:"Une dinde peut vivre une dizaine d'années.",
 note:"Les dindes d'élevage ne se reproduisent plus naturellement : les reproducteurs sont inséminés artificiellement.",
 ev:[
 {d:1,sc:{bg:"couvoir",n:16,who:"poussin"},pl:"poussin",x:"Tu sors de l'œuf dans un couvoir. On te coupe le bout du bec, pour limiter les coups de bec plus tard.",
  e:"Un dindon sauvage d'Amérique, dans une forêt du Kentucky : « Moi, je vole jusqu'aux branches pour dormir. »",
  f:"Le dindon sauvage peut voler sur de courtes distances et dort perché dans les arbres.",
  c:[{l:"Secouer la tête",r:"Ça brûle un peu. Puis moins.",p:1},{l:"Te taire",r:"Le tapis avance."}]},
 {d:42,x:"Tu cherches à picorer. Il n'y a que la litière et les autres.",
  e:"Un éleveur à sa femme : « Ils se piquent dès qu'ils s'ennuient. »",
  f:"Les dindes sont curieuses et reconnaissent les individus de leur groupe.",
  c:[{l:"Picorer la litière",r:"Tu trouves un copeau. Tu le lâches."},{l:"Picorer un voisin",r:"Il crie. Toi aussi, on te picore.",p:1}]},
 {d:84,sc:{n:40,who:"dinde"},x:"Tu as été sélectionné pour avoir une poitrine énorme. Si lourde que les dindons d'élevage ne peuvent plus s'accoupler naturellement.",
  e:"Un généticien, dans un colloque : « On a doublé la masse de filet en cinquante ans. »",
  f:"Un dindon commercial mâle peut dépasser 20 kg. Son ancêtre sauvage en pèse moins de la moitié.",
  c:[{l:"Marcher",r:"Tu fais quelques pas, en te balançant.",s:-1},{l:"Rester couché",r:"Tu restes couché la plus grande partie de la journée.",s:-1}]},
 {d:112,sc:{n:44,who:"dinde"},when:S=>S.lieu==="États-Unis",x:"Novembre. Le président des États-Unis va « gracier » une dinde à la Maison-Blanche. Ce ne sera pas toi.",
  e:"Un présentateur télé : « Et voici la dinde graciée cette année ! »",
  f:"Chaque année, environ 45 millions de dindes sont consommées aux États-Unis pour Thanksgiving. Deux sont graciées.",
  c:[{l:"Glouglouter",r:"Des milliers d'autres glougloutent avec toi."},{l:"Te taire",r:"Le bâtiment est bruyant sans toi."}]},
 {d:120,end:1,sc:{bg:"camion",n:12,who:"dinde",still:1},x:"Le bâtiment est vidé en une nuit.",
  e:"Une famille qui découpe une dinde : « Qui veut la cuisse ? »",
  f:"Les dindes femelles sont abattues vers 12 semaines, les mâles vers 16 à 20 semaines."}
 ]});

L("lapin",{nom:"Lapin",cat:"terre",poids:600,sprite:"lapin",sc:{bg:"cage",n:5,who:"lapin"},
 lieux:["Chine","France, Pays de la Loire","Italie","Espagne","Égypte"],cond:"Élevage en cage",
 nat:3285,natTxt:"Un lapin peut vivre de 8 à 10 ans.",
 note:"Dans l'Union européenne, la grande majorité des lapins d'élevage vivent en cage.",
 ev:[
 {d:1,sc:{n:6},x:"Tu nais dans un nid de poils que ta mère a arrachés à son propre ventre, au fond d'une cage de maternité.",
  e:"Un lapin de garenne, dans un talus : « Notre terrier fait vingt mètres de galeries. »",
  f:"La lapine ne vient allaiter qu'une ou deux fois par jour, quelques minutes. C'est normal chez les lapins.",
  c:[{l:"Te blottir",r:"Il fait chaud dans le nid.",p:-1},{l:"Chercher ta mère",r:"Elle viendra demain matin."}]},
 {d:35,x:"On te sépare de ta mère. Tu partages une cage grillagée avec cinq autres lapereaux. La cage est trop basse pour te dresser sur tes pattes arrière.",
  e:"Une enfant à la fenêtre d'une animalerie : « Maman, il fait des bonds ! »",
  f:"En 2021, la Commission européenne s'est engagée à proposer la fin des cages pour les animaux d'élevage, après l'initiative citoyenne « End the Cage Age ». La proposition se fait toujours attendre.",
  c:[{l:"Essayer de bondir",r:"Tu touches le plafond.",p:1},{l:"Creuser le sol",r:"Tes griffes glissent sur le grillage.",p:1}]},
 {alt:[
  {d:50,x:"Beaucoup de lapereaux ont la diarrhée. On ajoute des antibiotiques dans l'eau.",
   e:"Un pharmacien vétérinaire : « Le lapin est une des filières qui consomment le plus d'antibiotiques. »",
   f:"Les troubles digestifs sont la première cause de mortalité des lapins en élevage.",
   c:[{l:"Boire",r:"Tu bois. Tu tiens.",s:-1},{l:"Ne plus manger",r:"Tu maigris. Deux de tes compagnons de cage ne se relèvent pas.",s:-2,risk:{p:.15,t:"Ton ventre gonfle. Tu ne te relèves pas non plus."}}]},
  {d:50,x:"Il fait chaud. Les lapins supportent mal la chaleur.",
   e:"Un ventilateur, qui tourne au fond : il n'atteint pas ta cage.",
   f:"Au-dessus de 30 °C, les lapins peuvent mourir d'un coup de chaleur.",
   c:[{l:"T'allonger de tout ton long",r:"Tes oreilles sont brûlantes.",s:-1},{l:"Te coller au grillage",r:"Un peu d'air passe.",p:1}]}]},
 {d:72,end:1,sc:{bg:"camion",n:12,who:"lapin",still:1},x:"Tu pèses environ deux kilos et demi. On ouvre la cage.",
  e:"Un enfant qui caresse son lapin nain, dans un appartement en ville.",
  f:"Le lapin est à la fois l'un des animaux de compagnie les plus courants en France et un animal de boucherie."}
 ]});

L("porc",{nom:"Porc",cat:"terre",poids:1400,sprite:"porc",sc:{bg:"caillebotis",n:10},
 lieux:["Chine","Espagne","États-Unis","Allemagne","France, Bretagne","Brésil","Vietnam"],cond:"Bâtiment, sol en caillebotis",
 nat:5475,natTxt:"Un porc peut vivre une quinzaine d'années.",
 note:"La Chine élève près de la moitié des porcs du monde. En France, environ 95 % des porcs sont élevés en bâtiment.",
 ev:[
 {d:1,sc:{bg:"maternite",n:6},px:70,py:72,x:"Tu nais dans une maternité, avec une douzaine de frères et sœurs. Ta mère est dans une case métallique qui l'empêche de se retourner, pour qu'elle ne vous écrase pas.",
  e:"Un sanglier, à la lisière d'une forêt de Bretagne : « Ma laie fait un nid de branches avant la mise bas. »",
  f:"Avant de mettre bas, une truie construit instinctivement un nid. Dans une case de maternité, elle n'a rien pour le faire.",
  c:[{l:"Chercher une tétine",r:"Tu trouves ta place. Tu la défendras chaque jour."},{l:"Rester au chaud sous la lampe",r:"Tu as chaud. Les autres ont pris les meilleures tétines.",s:-1}]},
 {d:3,sc:{bg:"maternite",n:6,extra:"humain"},px:70,py:72,x:"Un soigneur te soulève. On te coupe le bout de la queue, pour que les autres ne te la mordent pas plus tard, quand vous serez à l'étroit.",
  e:"Un inspecteur européen, dans un rapport : « Pratique systématique constatée. »",
  f:"La coupe systématique de la queue est interdite par la directive européenne de 2008. Elle reste pratiquée dans la grande majorité des élevages.",
  c:[{l:"Crier",r:"Tu cries. Il te repose. C'est fini.",p:1},{l:"Te débattre",r:"Il te tient plus fort. Ça dure quelques secondes.",p:1}]},
 {d:5,when:S=>S.m,sc:{bg:"maternite",n:6,extra:"humain"},px:70,py:72,x:"Tu es un mâle. Le soigneur revient, avec un scalpel. On castre les mâles pour éviter l'odeur de leur viande.",
  e:"Une éleveuse danoise : « Chez nous, on a des vaccins contre l'odeur. Pas besoin de castrer. »",
  f:"En France, la castration à vif des porcelets est interdite depuis 2022 : il faut une anesthésie ou un traitement contre la douleur.",
  c:[{l:"Crier",r:"Tu cries. On te repose sous la lampe.",s:-1,p:2},{l:"Te figer",r:"Ça dure moins d'une minute.",s:-1,p:1}]},
 {d:25,sc:{n:14},x:"On te sépare de ta mère. Dans la nature, un porcelet tète jusqu'à trois ou quatre mois.",
  e:"Ta mère, de l'autre côté du bâtiment, qui t'appelle.",
  f:"En élevage, les porcelets sont sevrés vers 3 à 4 semaines. Les truies peuvent ainsi être inséminées de nouveau plus vite.",
  c:[{l:"L'appeler",r:"Tu l'appelles longtemps. Elle ne répond pas.",p:2},{l:"Suivre les autres",r:"Vous êtes nombreux dans la nouvelle case. Tu restes collé à ta fratrie.",p:1}]},
 {d:60,sc:{n:12},x:"Tu as compris qu'un bruit de chariot veut dire repas. Tu reconnais chacun des autres porcs à l'odeur.",
  e:"Une chercheuse en éthologie : « On a appris à des porcs à jouer à un jeu vidéo avec un joystick. »",
  f:"En 2021, des chercheurs de l'université Purdue ont montré que des porcs pouvaient apprendre à déplacer un curseur avec un joystick.",
  c:[{l:"Courir vers l'auge",r:"Tu arrives le premier. Tu le sais pour la prochaine fois."},{l:"Observer les autres",r:"Tu sais maintenant qui mange en premier, et qui se bat."}]},
 {d:90,sc:{n:12},x:"Ta case a un sol de lattes de béton ajourées, pour laisser passer les excréments. Le porc est un animal qui aime fouiller la terre. Ici, il n'y a pas de terre.",
  e:"Un cochon de ferme pédagogique, dans un enclos boueux : « Je fouille six heures par jour. »",
  f:"La réglementation européenne impose de donner aux porcs des matériaux à manipuler. Dans beaucoup d'élevages, c'est une simple chaîne ou un bloc de bois.",
  c:[{l:"Mâchouiller la chaîne",r:"C'est le seul objet de la case. Tu y reviens souvent."},{l:"Mordiller l'oreille d'un voisin",r:"Il crie. L'ennui fait ça, à tout le monde ici.",p:1},{l:"Dormir",r:"Tu dors beaucoup. Il n'y a pas grand-chose d'autre à faire."}]},
 {alt:[
  {d:130,sc:{n:12},x:"Une toux circule dans le bâtiment. On ajoute un traitement dans l'eau de tout le monde.",
   e:"Un épidémiologiste : « Les élevages denses sont des incubateurs pour les virus grippaux. »",
   f:"La grippe porcine H1N1 de 2009 est issue de virus qui circulaient chez les porcs.",
   c:[{l:"Boire",r:"Tu bois. Tu guéris.",s:-1},{l:"Te coucher dans un coin",r:"Tu tousses une semaine.",s:-2}]},
  {d:130,sc:{n:12},when:S=>S.lieu==="Chine"||S.lieu==="Vietnam",x:"Des hommes en combinaison entrent dans le bâtiment. La peste porcine africaine a été détectée dans la région.",
   e:"Un éleveur, en larmes au téléphone : « Tout le cheptel. Tout. »",
   f:"Entre 2018 et 2020, la peste porcine africaine a fait chuter le cheptel porcin chinois d'environ 40 %.",
   c:[{l:"Reculer au fond",r:"Ils ne viennent pas pour toi. Pas encore.",p:2,risk:{p:.5,t:"Tout le bâtiment est abattu par précaution. Tu fais partie du lot."}},{l:"T'approcher",r:"L'un d'eux prélève du sang à ton oreille. Tu es négatif.",p:1}]}]},
 {d:170,sc:{bg:"camion",n:8,who:"porc",still:1},x:"Tu pèses environ 115 kilos. La porte de la case s'ouvre. On vous fait avancer dans un couloir, vers un camion.",
  e:"Un client au rayon charcuterie : « Six tranches de jambon, s'il vous plaît. »",
  f:"Un porc charcutier est abattu vers 6 mois. En France, l'étourdissement au CO₂ est la méthode la plus courante.",
  c:[{l:"Avancer",r:"Tu avances avec les autres.",fin:1},{l:"Refuser d'avancer",r:"On te pousse. Tu avances.",p:2,fin:1}]}
 ]});

L("truie",{nom:"Truie reproductrice",cat:"terre",poids:40,sprite:"porc",sc:{bg:"maternite",n:6},
 lieux:["France, Bretagne","Espagne","Danemark","États-Unis","Chine"],cond:"Élevage naisseur",
 nat:5475,natTxt:"Une truie peut vivre une quinzaine d'années.",
 note:"Une truie d'élevage met bas environ 2,3 fois par an et donne naissance à près de 30 porcelets par an.",
 ev:[
 {d:200,sc:{bg:"caillebotis",n:8},x:"Tu as été sélectionnée pour devenir reproductrice. Tes sœurs sont parties à l'abattoir. Toi, tu restes.",
  e:"Une truie sauvage, dans un bois : « Une portée par an, dans un nid de feuilles. »",
  f:"Les truies modernes sont sélectionnées pour avoir de grandes portées, souvent plus de 14 porcelets.",
  c:[{l:"Rester près de la barrière",r:"Tu regardes tes sœurs monter dans le camion.",p:1},{l:"Manger",r:"Tu manges. On t'a mise au régime pour ne pas grossir trop vite."}]},
 {d:240,sc:{bg:"caillebotis",n:6,extra:"eleveur"},x:"Premier passage : un verrat passe devant ta case pour te mettre en chaleur, puis on t'insémine. Tu es placée dans une case individuelle où tu ne peux pas te retourner.",
  e:"Une sénatrice européenne : « Il est temps de sortir les truies des cages. »",
  f:"Dans l'Union européenne, les truies peuvent être bloquées en case individuelle pendant 4 semaines après l'insémination, puis en groupe.",
  c:[{l:"Mordre les barreaux",r:"Tu mords les barreaux pendant des heures. C'est un geste que tu répéteras.",p:2},{l:"Te coucher",r:"Tu te couches. Il n'y a que ça à faire.",s:-1}]},
 {d:354,x:"Tu entres en maternité. Avant la mise bas, ton corps te pousse à construire un nid. Tu grattes le sol métallique.",
  e:"Ta grand-mère, si elle avait vécu en forêt : « Il faut des branches. »",
  f:"La gestation d'une truie dure 3 mois, 3 semaines et 3 jours.",
  c:[{l:"Gratter le sol",r:"Tu grattes jusqu'à t'en faire saigner les sabots.",s:-1,p:2},{l:"Ronger la barre",r:"Tu ronges la barre. Puis les petits arrivent."}]},
 {d:356,x:"Quinze porcelets. Tu ne peux ni te retourner pour les voir, ni les lécher.",
  e:"Le soigneur, doucement : « Bravo, ma grosse. Quinze. »",
  f:"Dans les grandes portées, plusieurs porcelets meurent souvent dans les premiers jours : écrasement, faiblesse, froid.",
  c:[{l:"Grogner doucement",r:"Ils viennent téter quand tu grognes.",p:-2},{l:"Rester immobile",r:"Tu restes immobile pour ne pas les écraser.",s:-1}]},
 {d:380,x:"On t'enlève tes porcelets. Cinq jours plus tard, tu es de nouveau inséminée.",
  e:"Tes porcelets, de l'autre côté du mur.",
  f:"Ce cycle se répète en moyenne 5 à 6 fois.",
  c:[{l:"Appeler",r:"Personne ne répond.",p:2},{l:"Manger",r:"Il faut reprendre des forces."}]},
 {d:1000,x:"C'est ta sixième portée. Tes pattes te font mal. Tu as moins de porcelets que l'an dernier.",
  e:"Le registre de l'éleveur : une colonne de chiffres qui baisse.",
  f:"Les truies sont réformées en moyenne vers 2 à 3 ans, quand leur productivité baisse ou qu'elles boitent.",
  c:[{l:"Te lever pour manger",r:"Ça prend du temps.",s:-1},{l:"Rester couchée",r:"On t'observe plus longtemps que d'habitude.",s:-1}]},
 {d:1050,end:1,sc:{bg:"camion",n:4,who:"porc",still:1},x:"On te fait monter dans le camion. Tu as donné naissance à environ quatre-vingt-dix porcelets.",
  e:"Un saucisson dans une épicerie fine.",
  f:"La viande de truie de réforme sert surtout à la charcuterie et au saucisson."}
 ]});

L("agneau",{nom:"Agneau",cat:"terre",poids:600,sprite:"mouton",sc:{bg:"pre",n:10},
 lieux:["France, Aveyron","France, Hautes-Alpes","Royaume-Uni, pays de Galles","Irlande","Nouvelle-Zélande"],cond:"Élevage au pré et en bergerie",
 nat:4380,natTxt:"Un mouton peut vivre de 10 à 12 ans.",
 note:"Les agneaux passent souvent une partie de leur vie au pré, ce qui n'est pas le cas de la plupart des volailles et des porcs.",
 ev:[
 {d:1,sc:{bg:"etable",n:8},x:"Tu nais dans la bergerie, au printemps. Ta mère te reconnaît à l'odeur et à la voix parmi des dizaines d'agneaux.",
  e:"Un mouflon, sur une crête de Corse : « Mes petits naissent dans la rocaille. »",
  f:"Une brebis reconnaît son agneau à la voix quelques heures après la naissance. Les moutons reconnaissent aussi les visages, y compris humains.",
  c:[{l:"Téter",r:"Le lait est chaud. Ta mère te pousse du museau.",p:-1},{l:"Tenir debout",r:"Tu tombes deux fois. La troisième, tu tiens."}]},
 {d:30,x:"On vous sort au pré. L'herbe, le vent, la pluie. Tu cours avec les autres agneaux sans aucune raison.",
  e:"Une randonneuse, qui sort son téléphone : « Regarde-les sauter ! »",
  f:"Les agneaux jouent beaucoup : courses, sauts, défis. Le jeu est un indicateur de bien-être chez les jeunes animaux.",
  c:[{l:"Courir",r:"Tu sautes sur place, les quatre pattes en l'air.",p:-2},{l:"Rester contre ta mère",r:"Elle broute. Tu la regardes faire.",p:-1}]},
 {d:60,sc:{extra:"eleveur"},x:"L'éleveur te pose une boucle jaune à l'oreille, avec ton numéro. On pose aussi un anneau de caoutchouc sur ta queue : elle tombera dans quelques semaines.",
  e:"Une brebis plus âgée : « Moi aussi, j'ai ma boucle. »",
  f:"La coupe de la queue des agneaux se fait pour limiter les infestations de mouches. Elle est souvent pratiquée sans anesthésie.",
  c:[{l:"Secouer la tête",r:"La boucle tient.",p:1},{l:"Retourner vers ta mère",r:"Elle te sent, et reprend sa place dans le troupeau."}]},
 {alt:[
  {d:120,when:S=>S.lieu.startsWith("France"),x:"Un loup a attaqué un troupeau dans la vallée voisine. Le berger rentre les brebis chaque soir, avec deux chiens patous.",
   e:"Un loup, sur la crête, la nuit : il vous regarde.",
   f:"Le loup est revenu naturellement en France en 1992. Les éleveurs dont les troupeaux sont attaqués peuvent être indemnisés.",
   c:[{l:"Suivre les chiens",r:"Tu rentres au trot. Tu apprends le chemin.",p:1},{l:"Traîner derrière",r:"Un chien vient te chercher.",p:1,risk:{p:.06,t:"Le soir tombe trop vite. Le loup est plus rapide que le chien."}}]},
  {d:120,x:"La sécheresse a jauni l'herbe. Le berger apporte du foin au pré.",
   e:"Le berger, à son voisin : « Troisième été comme ça. »",
   f:"Les sécheresses répétées obligent de nombreux éleveurs à acheter du fourrage dès l'été.",
   c:[{l:"Manger le foin",r:"C'est sec, mais il y en a assez."},{l:"Chercher de l'herbe verte",r:"Tu en trouves près du ruisseau.",p:-1}]}]},
 {d:150,sc:{bg:"etable",n:12},x:"On te sépare de ta mère pour finir ta croissance en bergerie.",
  e:"Ta mère, de l'autre côté de la cloison, qui bêle toute la nuit.",
  f:"La plupart des agneaux de boucherie sont abattus entre 3 et 6 mois. La demande culmine à Pâques et à l'Aïd el-Kébir.",
  c:[{l:"L'appeler",r:"Tu bêles toute la nuit. Les autres aussi.",p:2},{l:"Manger",r:"Il y a du grain. Tu manges."}]},
 {d:180,end:1,sc:{bg:"camion",n:10,who:"mouton",still:1},x:"Le camion arrive au petit matin.",
  e:"Une famille autour d'un gigot, le dimanche.",
  f:"La France importe environ 60 % de la viande ovine qu'elle consomme, surtout du Royaume-Uni, d'Irlande, d'Espagne et de Nouvelle-Zélande."}
 ]});

L("chevreau",{nom:"Chevreau",cat:"terre",poids:500,sprite:"chevre",sc:{bg:"etable",n:10,who:"chevre"},
 lieux:["France, Deux-Sèvres","France, Vienne","France, Ardèche","Espagne, Andalousie"],cond:"Élevage laitier",
 nat:5475,natTxt:"Une chèvre peut vivre une quinzaine d'années.",
 note:"Pour produire du lait de chèvre, les chèvres doivent mettre bas chaque année. Les chevreaux mâles n'ont pas d'utilité pour la filière laitière.",
 ev:[
 {d:1,x:"Tu nais dans une chèvrerie. Tu es un mâle. Ta mère te lèche. Une heure plus tard, on vous sépare.",
  e:"Un chevreau des Alpes, dans un alpage : « Moi, je suis ma mère partout, sur les rochers. »",
  f:"La France est l'un des premiers producteurs européens de lait de chèvre, surtout pour le fromage.",
  c:[{l:"Bêler",r:"Elle te répond. On l'emmène à la traite.",p:2},{l:"Chercher une tétine",r:"On te donne un biberon de lait en poudre."}]},
 {d:8,sc:{bg:"camion",n:14,who:"chevre"},x:"Tu as une semaine. Un camion vient chercher les chevreaux mâles pour un atelier d'engraissement.",
  e:"Un fromager au marché : « Crottin de Chavignol, affiné trois semaines. »",
  f:"La plupart des chevreaux mâles des élevages laitiers sont vendus à quelques jours à des engraisseurs.",
  c:[{l:"Te coller aux autres",r:"Vous êtes nombreux. Vous tremblez ensemble.",p:1},{l:"Bêler",r:"Le camion démarre.",p:2}]},
 {d:20,sc:{bg:"hangar",n:30,who:"chevre"},x:"Tu bois au seau, avec des dizaines d'autres chevreaux. Tu sautes partout dès que tu peux.",
  e:"Une vidéo de chevreaux en pyjama, 12 millions de vues.",
  f:"Les chevreaux sont parmi les animaux d'élevage les plus joueurs. Ils grimpent sur tout ce qu'ils trouvent.",
  c:[{l:"Grimper sur un autre",r:"Il te renverse. Vous recommencez.",p:-2},{l:"Boire",r:"Tu bois tout le seau.",s:1}]},
 {d:45,end:1,sc:{bg:"camion",n:12,who:"chevre",still:1},x:"Tu as six semaines.",
  e:"Une famille qui cuisine un chevreau rôti pour Pâques, dans le sud de l'Europe.",
  f:"Le chevreau est abattu vers 6 semaines. Une grande partie de la viande française est exportée vers l'Italie, l'Espagne et le Portugal."}
 ]});

L("bovin",{nom:"Bovin à viande",cat:"terre",poids:230,sprite:"boeuf",sc:{bg:"pre",n:5,who:"boeuf"},
 lieux:["France, Charolais","États-Unis, Texas","Brésil, Mato Grosso","Argentine","Australie"],cond:"Élevage allaitant",
 nat:7300,natTxt:"Un bovin peut vivre une vingtaine d'années.",
 note:"Le bœuf est la viande dont la production émet le plus de gaz à effet de serre par kilo.",
 ev:[
 {d:1,x:"Tu nais au pré, au printemps. Ta mère te lèche longtemps. Tu restes avec elle.",
  e:"Un aurochs, ton ancêtre éteint en 1627 : « Nous, on était deux fois plus grands. »",
  f:"Dans les races à viande, le veau reste avec sa mère et tète pendant 6 à 9 mois.",
  c:[{l:"Téter",r:"Tu tètes. Ta mère rumine.",p:-1},{l:"Explorer le pré",r:"Tu découvres une haie, un ruisseau, une clôture électrique.",p:1}]},
 {d:60,sc:{extra:"eleveur"},x:"On te coupe les bourgeons de cornes, au fer chaud.",
  e:"Un veau d'une race sans cornes, dans le pré voisin : « Moi, je suis né comme ça. »",
  f:"L'écornage est courant pour limiter les blessures entre animaux et pour les éleveurs. En France, l'anesthésie n'est pas obligatoire avant l'âge de 4 semaines.",
  c:[{l:"Te débattre",r:"Ça dure quelques secondes.",s:-1,p:2},{l:"Te figer",r:"L'odeur de corne brûlée reste longtemps.",p:1}]},
 {d:270,when:has("France"),sc:{bg:"camion",n:6,who:"boeuf"},x:"On te sépare de ta mère. Tu es un broutard. Un camion t'emmène vers l'Italie, pour y être engraissé.",
  e:"Un éleveur italien : « Les meilleurs broutards viennent de France. »",
  f:"La France exporte chaque année environ 900 000 broutards. Près de 80 % partent en Italie pour y être engraissés.",
  c:[{l:"Appeler ta mère",r:"Tu l'appelles pendant deux jours de route.",p:2},{l:"Te coucher dans le camion",r:"Le camion est secoué. Tu ne dors pas."}]},
 {d:270,when:has("États-Unis"),sc:{bg:"feedlot",n:24,who:"boeuf"},x:"On te sépare de ta mère. On t'emmène dans un parc d'engraissement, un feedlot. Des dizaines de milliers de bovins, sur de la terre battue, sans un brin d'herbe.",
  e:"Un pilote d'avion, au-dessus du Texas : « On les voit à des kilomètres. »",
  f:"Aux États-Unis, la majorité des bovins à viande finissent leur vie dans des feedlots, nourris au maïs.",
  c:[{l:"Manger le maïs",r:"Ton estomac est fait pour l'herbe. Tu gonfles.",s:-1},{l:"Chercher de l'ombre",r:"Il n'y en a pas.",s:-1,p:1}]},
 {d:270,when:has("Brésil"),sc:{bg:"palmiers",n:6,who:"boeuf"},x:"Ton pâturage était une forêt il y a cinq ans. On voit encore des souches brûlées.",
  e:"Un jaguar, à la lisière de ce qui reste de forêt : il recule un peu plus chaque année.",
  f:"L'élevage bovin est la première cause de déforestation en Amazonie.",
  c:[{l:"Brouter",r:"L'herbe est maigre sur la terre brûlée."},{l:"Te mettre à l'ombre d'une souche",r:"Il fait 38 degrés.",s:-1}]},
 {d:270,when:S=>has("Argentine")(S)||has("Australie")(S),x:"Tu restes au pâturage, dans d'immenses prairies. Tu vois rarement un humain.",
  e:"Un gaucho, à cheval : « Ici, ils vivent comme leurs ancêtres. Ou presque. »",
  f:"En Argentine et en Australie, une partie des bovins est élevée à l'herbe, sur de très grandes surfaces.",
  c:[{l:"Suivre le troupeau",r:"Vous marchez des kilomètres par jour.",p:-1},{l:"Rester près de l'eau",r:"Tu bois. La sécheresse menace.",s:-1}]},
 {d:540,end:1,sc:{bg:"camion",n:6,who:"boeuf",still:1},x:"Tu as environ 18 mois. Tu pèses plus de 600 kilos.",
  e:"Un client au restaurant : « Une entrecôte, saignante. »",
  f:"Un kilo de bœuf issu d'un troupeau allaitant émet en moyenne près de 100 kg d'équivalent CO₂, contre environ 10 kg pour le poulet (Poore et Nemecek, 2018)."}
 ]});

L("veau",{nom:"Veau laitier",cat:"terre",poids:60,sprite:"veau",sc:{bg:"etable",n:6,who:"vache"},
 lieux:["France, Bretagne","Pays-Bas","Irlande","Allemagne","Nouvelle-Zélande"],cond:"Né dans un élevage laitier",
 nat:7300,natTxt:"Un bovin peut vivre une vingtaine d'années.",
 note:"Pour qu'une vache donne du lait, elle doit avoir un veau chaque année. Les veaux mâles des races laitières sont peu valorisés.",
 ev:[
 {d:1,x:"Tu nais dans une étable. Tu es un mâle. Ta mère est une Prim'Holstein. On te met dans une niche en plastique, seul.",
  e:"Un enfant devant une brique de lait : « Le lait, ça vient des vaches. »",
  f:"Dans l'Union européenne, un veau peut être logé seul jusqu'à 8 semaines.",
  c:[{l:"Appeler ta mère",r:"Elle t'entend. On l'emmène à la traite.",p:2},{l:"Boire le lait au seau",r:"On te donne du colostrum. Tu bois.",s:1}]},
 {d:14,when:S=>S.lieu==="Irlande"||S.lieu==="Pays-Bas",sc:{bg:"camion",n:10,who:"veau"},x:"Tu as deux semaines. Un camion t'emmène vers un autre pays : plus de 20 heures de route, puis un ferry.",
  e:"Un chauffeur routier : « On s'arrête, on les abreuve, on repart. »",
  f:"En 2024, l'Irlande a exporté environ 190 000 veaux laitiers de quelques semaines, surtout vers les Pays-Bas et l'Espagne.",
  c:[{l:"Te coucher",r:"Le sol vibre. Tu ne dors pas.",s:-1,p:1},{l:"Rester debout",r:"Tu tombes deux fois quand le camion freine.",s:-1,p:2}]},
 {d:14,when:S=>S.lieu!=="Irlande"&&S.lieu!=="Pays-Bas",sc:{bg:"camion",n:10,who:"veau"},x:"Tu as deux semaines. Un marchand t'achète. Tu pars vers un atelier d'engraissement de veaux de boucherie.",
  e:"Un marchand de bestiaux, au marché aux veaux : « Prim'Holstein mâle, quatre-vingts euros. »",
  f:"Un veau mâle laitier se vend souvent bien moins cher qu'un veau de race à viande.",
  c:[{l:"Suivre les autres",r:"Vous montez dans le camion.",p:1},{l:"Refuser de monter",r:"On te pousse.",p:2}]},
 {d:90,sc:{bg:"hangar",n:20,who:"veau"},x:"Tu vis en case collective sur caillebotis. On te nourrit au lait reconstitué. Tu as envie de téter ; tu tètes les oreilles des autres veaux.",
  e:"Un cuisinier : « Blanquette de veau, la viande doit être blanche. »",
  f:"Le veau de boucherie est nourri surtout au lait. Sa viande est plus claire quand son alimentation contient peu de fer.",
  c:[{l:"Téter l'oreille d'un voisin",r:"Il se laisse faire. Puis il tète la tienne.",p:-1},{l:"Mâchouiller la barrière",r:"Tu cherches du foin. Il y en a un peu.",p:1}]},
 {d:180,end:1,sc:{bg:"camion",n:10,who:"veau",still:1},x:"Tu as six mois.",
  e:"Une vache laitière, ta mère, qui vient d'avoir un autre veau.",
  f:"Un veau de boucherie est abattu vers 6 mois. La France est le premier consommateur de veau en Europe."}
 ]});

L("vache",{nom:"Vache laitière",cat:"terre",poids:30,sprite:"vache",sc:{bg:"etable",n:4},
 lieux:["États-Unis","Nouvelle-Zélande","France, Normandie","Allemagne","Pays-Bas","Inde"],cond:"Élevage laitier",
 nat:7300,natTxt:"Une vache peut vivre une vingtaine d'années.",
 note:"Une vache laitière moderne produit souvent plus de 8 000 litres de lait par an, bien plus qu'un veau n'en boirait.",
 ev:[
 {d:1,x:"Tu nais dans une étable. Ta mère te lèche quelques minutes. Puis on t'emmène dans une case individuelle : son lait est destiné à la vente.",
  e:"Une vache d'Hérens, dans un alpage suisse : « Chez nous, les veaux restent un peu plus longtemps. »",
  f:"Dans la plupart des élevages laitiers, le veau est séparé de sa mère dans les heures ou les jours qui suivent sa naissance.",
  c:[{l:"Appeler ta mère",r:"Elle te répond, de l'autre côté du bâtiment. Pendant deux jours.",p:2},{l:"Boire au seau",r:"On t'apprend à boire au seau. Tu apprends."}]},
 {d:180,when:S=>S.lieu!=="Inde",sc:{bg:"pre",n:6},x:"Tu passes l'été au pré avec les autres génisses. Vous vous léchez, vous vous poussez, vous dormez en tas.",
  e:"Un cycliste du Tour de France, qui passe à toute vitesse devant le pré.",
  f:"Les vaches forment des amitiés. Des études montrent que leur rythme cardiaque baisse quand elles sont avec une compagne préférée.",
  c:[{l:"Jouer avec une autre génisse",r:"Vous vous poussez front contre front, sans vous faire mal.",p:-2},{l:"Brouter",r:"L'herbe est bonne.",p:-1}]},
 {d:450,x:"Un inséminateur vient. Pour produire du lait, une vache doit d'abord avoir un veau.",
  e:"Un taureau, dans un centre de sélection génétique : il n'a jamais rencontré de vache.",
  f:"La grande majorité des vaches laitières en France sont inséminées artificiellement.",
  c:[{l:"Rester calme",r:"C'est rapide."},{l:"Bouger",r:"On te bloque la tête au cornadis. C'est rapide quand même.",p:1}]},
 {d:730,when:S=>S.lieu==="Inde",sc:{bg:"inde",n:2,who:"vache"},x:"Ton premier veau naît. Ta famille le garde près de toi pour que ton lait descende, puis te trait à la main, à l'aube, devant la maison.",
  e:"",hu:"Ta famille — vit en partie de ton lait.",f:"En Inde, une grande partie du lait vient de petits troupeaux familiaux de quelques vaches ou bufflonnes.",
  c:[{l:"Lécher ton veau",r:"Il reste à côté de toi pendant la traite.",p:-2},{l:"Te laisser traire",r:"Le lait part dans des bidons en aluminium.",s:-1}]},
 {d:730,when:S=>S.lieu!=="Inde",sc:{bg:"traite",n:5},x:"Ton premier veau naît. On l'emmène, comme on t'a emmenée. Tu entres dans la salle de traite, deux fois par jour.",
  e:"Un robot de traite, dans la ferme voisine : il trait les vaches quand elles le décident.",
  f:"Dans les fermes équipées de robots, ce sont les vaches qui choisissent quand se faire traire.",
  c:[{l:"Le chercher du regard",r:"Tu l'appelles longtemps.",p:2},{l:"Suivre le troupeau",r:"Tu apprends le chemin. Tu le feras des milliers de fois."}]},
 {d:1100,when:S=>S.lieu!=="Inde",sc:{bg:"traite",n:5},x:"Tu produis beaucoup plus de lait qu'un veau n'en boirait. Tu es de nouveau inséminée.",
  e:"Le laitier qui collecte le lait : « 0,45 € le litre. Ça ne couvre pas les coûts. »",
  f:"Le prix du lait payé aux éleveurs français tourne autour de 40 à 50 centimes le litre selon les années.",
  c:[{l:"Manger tout ce qu'on te donne",r:"Ton corps puise dans ses réserves quand même.",s:-1},{l:"Te coucher dès que possible",r:"Tu passes de longues heures couchée, à ruminer."}]},
 {d:1100,when:S=>S.lieu==="Inde",sc:{bg:"inde",n:3,who:"vache"},x:"Ta famille vit en ville. On te trait le matin, puis tu passes la journée dans la rue, entre les voitures et les marchés.",
  e:"Un passant qui te touche le front avant d'aller au temple.",
  f:"L'Inde est le premier producteur de lait au monde. La vache y est sacrée pour une grande partie des hindous.",
  c:[{l:"Manger les épluchures du marché",r:"Un marchand te donne des feuilles de chou.",s:1},{l:"Fouiller une poubelle",r:"Tu avales un sac en plastique.",s:-2}]},
 {alt:[
  {d:1460,sc:{bg:"traite",n:5},when:S=>S.lieu!=="Inde",x:"Ton pis est lourd, et une mammite s'est déclarée : une infection douloureuse.",
   e:"Une vétérinaire : « La mammite, c'est la maladie la plus fréquente chez la vache laitière. »",
   f:"La mammite est l'une des principales raisons d'utilisation d'antibiotiques en élevage laitier.",
   c:[{l:"Te coucher",r:"On te soigne. Ton lait est jeté pendant le traitement.",s:-1},{l:"Rester debout",r:"Tu restes debout, le pis brûlant.",s:-2}]},
  {d:1460,when:S=>S.lieu!=="Inde",x:"Tu boites. Le béton a usé tes onglons. Chaque trajet vers la traite te fait mal.",
   e:"Un pareur, qui passe une fois par trimestre : « Une sur quatre boite un peu. »",
   f:"Les boiteries touchent une part importante des vaches laitières, en particulier dans les élevages sans pâturage.",
   c:[{l:"Avancer quand même",r:"Tu avances. Le parage soulage un peu.",s:-1},{l:"Rester en arrière",r:"On te pousse doucement vers la salle de traite.",s:-1,p:1}]}]},
 {d:1825,when:S=>S.lieu!=="Inde",end:1,sc:{bg:"camion",n:3,who:"vache",still:1},x:"Tu as eu trois veaux. Ta production baisse. Tu es réformée : tu pars à l'abattoir, comme la plupart des vaches laitières.",
  e:"Un client au fast-food : « Un double cheese. »",
  f:"La viande des vaches laitières de réforme sert surtout à la viande hachée."},
 {d:5400,when:S=>S.lieu==="Inde",end:1,sc:{bg:"inde",n:4,who:"vache"},x:"Ton lait s'est tari. Ta famille ne peut plus te nourrir. On t'emmène dans une goshala, un refuge pour vaches âgées, où tu finis tes jours.",
  e:"Un bénévole de la goshala : « Nous en avons trois cents. Il en arrive chaque semaine. »",
  f:"L'abattage des vaches est interdit dans la plupart des États indiens. Beaucoup de vaches âgées finissent dans des refuges, d'autres errent en ville."}
 ]});

L("buffle",{nom:"Buffle",cat:"terre",poids:30,sprite:"buffle",sc:{bg:"etang",n:5,who:"buffle"},
 lieux:["Inde, Uttar Pradesh","Pakistan","Italie, Campanie","Égypte","Népal"],cond:"Élevage laitier",
 nat:9000,natTxt:"Un buffle peut vivre 25 ans.",
 note:"Il y a environ 200 millions de buffles domestiques dans le monde, surtout en Asie du Sud.",
 ev:[
 {d:1,x:"Tu nais au bord d'un étang. Tu es un mâle. Ta mère est une bufflonne laitière.",
  e:"Un buffle sauvage d'Asie, dans un parc national d'Assam : « On n'est plus que quelques milliers. »",
  f:"L'Inde est le premier exportateur mondial de viande de buffle.",
  c:[{l:"Téter",r:"Tu tètes un peu. Le reste du lait est pour la famille.",p:-1},{l:"Suivre ta mère dans l'eau",r:"L'eau est fraîche.",p:-1}]},
 {d:20,when:has("Italie"),x:"Dans la Campanie, le lait de bufflonne sert à la mozzarella. Un mâle comme toi n'a pas de valeur.",
  e:"Un touriste, à Naples : « La vraie mozzarella di bufala, rien à voir. »",
  f:"Des enquêtes ont montré que des bufflons mâles nés dans des élevages de Campanie étaient abandonnés ou laissés mourir de faim, faute de débouché.",
  c:[{l:"Appeler",r:"Personne ne vient.",s:-2,p:2},{l:"Te coller à ta mère",r:"On te sépare d'elle.",p:2}]},
 {d:40,when:has("Italie"),end:1,sc:{dark:.3},x:"Tu as quelques semaines.",
  e:"Un pot de mozzarella AOP dans un supermarché de Lyon.",
  f:"Depuis ces enquêtes, la filière a renforcé les contrôles. Les bufflons sont désormais censés être identifiés et engraissés."},
 {d:900,when:S=>!has("Italie")(S),sc:{bg:"champ",n:2,who:"buffle",extra:"eleveur"},x:"Tu tires une charrue dans les rizières. Ton éleveur te parle en travaillant.",
  e:"Un tracteur chinois, neuf, dans la ferme d'à côté.",
  f:"Le buffle reste un animal de trait dans une partie de l'Asie, même si les machines le remplacent.",
  c:[{l:"Tirer fort",r:"Le sillon avance. On te donne de l'eau.",s:-1},{l:"Te coucher dans la boue",r:"Il fait 40 degrés. Ton éleveur attend que tu te relèves.",p:-1}]},
 {d:2200,when:S=>!has("Italie")(S),end:1,sc:{bg:"camion",n:4,who:"buffle",still:1},x:"Ton éleveur a acheté un motoculteur. Tu es vendu à un marchand.",
  e:"Un plat de viande de buffle dans un restaurant de Kuala Lumpur.",
  f:"La viande de buffle indienne est exportée surtout vers l'Asie du Sud-Est et le Moyen-Orient."}
 ]});

L("cheval",{nom:"Poulain de trait",cat:"terre",poids:5,sprite:"comtois",sc:{bg:"pre",n:4,who:"comtois"},
 lieux:["France, Jura","France, Auvergne","France, Bretagne","France, Haute-Saône"],cond:"Élevage de chevaux de trait",
 nat:10950,natTxt:"Un cheval peut vivre 25 à 30 ans.",
 note:"Les races de trait ont échappé à la disparition en partie grâce à la boucherie. La majorité de la viande de cheval consommée en France est importée.",
 ev:[
 {d:1,x:"Tu nais au pré, une nuit de printemps. Tu tiens debout au bout d'une heure.",
  e:"Un cheval de Przewalski, en Mongolie : « Nous avons été sauvés de l'extinction. »",
  f:"Un poulain tient debout et tète dans les deux premières heures après sa naissance.",
  c:[{l:"Gambader",r:"Tes jambes sont trop longues. Tu tombes. Tu recommences.",p:-1},{l:"Rester contre ta mère",r:"Elle te protège de son corps.",p:-1}]},
 {d:180,x:"Tu vis au pré avec ta mère et les autres juments. Tu joues avec les autres poulains.",
  e:"Un concours de race, à la foire : les plus beaux sont gardés pour la reproduction.",
  f:"Seule une petite partie des poulains de trait sont gardés pour la reproduction, le travail ou le loisir.",
  c:[{l:"Jouer avec les autres",r:"Vous vous mordillez l'encolure.",p:-1},{l:"Rester avec ta mère",r:"Tu es encore un peu petit."}]},
 {d:300,sc:{extra:"eleveur"},x:"On te sèvre. L'éleveur regarde tes aplombs, ta robe, ton modèle.",
  e:"Un juge de concours : « Bon modèle, mais trop léger. »",
  f:"Beaucoup de poulains de trait sont vendus pour la boucherie entre 10 et 18 mois.",
  c:[{l:"Te tenir droit",r:"L'éleveur hoche la tête.",luck:{p:.25,f:"garde",yes:"Il te garde. Tu seras cheval de travail en forêt.",no:"Il note quelque chose sur son carnet. Ce n'est pas bon."}},{l:"Fuir au fond du pré",r:"Il ne te court pas après."}]},
 {d:450,when:S=>!S.f.garde,end:1,sc:{bg:"camion",n:3,who:"comtois",still:1},x:"Tu as environ quinze mois.",
  e:"Un boucher chevalin, l'un des derniers de sa ville.",
  f:"La consommation de viande de cheval a fortement baissé en France depuis les années 1960."},
 {d:7300,when:S=>S.f.garde,end:1,sc:{bg:"bois",n:0},x:"Tu as débardé du bois en forêt pendant quinze ans, là où les machines abîmaient trop le sol. Tu as fini ta vie au pré.",
  e:"Un forestier : « Un cheval, ça ne tasse pas le sol. Ça ne pollue pas. »",
  f:"Le débardage à cheval connaît un petit renouveau dans les forêts sensibles."}
 ]});

L("chameau",{nom:"Dromadaire",cat:"terre",poids:3,sprite:"chameau",sc:{bg:"desert",n:4,who:"chameau"},
 lieux:["Somalie","Mauritanie","Arabie saoudite","Kenya","Soudan"],cond:"Élevage pastoral",
 nat:14600,natTxt:"Un dromadaire peut vivre 40 ans.",
 note:"La Somalie possède l'un des plus grands cheptels de dromadaires au monde. Leur lait nourrit des millions de pasteurs.",
 ev:[
 {d:1,x:"Tu nais dans le désert, à côté d'un campement. Ta mère te pousse du museau pour que tu te lèves.",
  e:"Un dromadaire sauvage d'Australie, descendant de bêtes importées au XIXe siècle : « Nous sommes des centaines de milliers là-bas. »",
  f:"L'Australie compte la plus grande population de dromadaires sauvages au monde.",
  c:[{l:"Te lever",r:"Tu te lèves en dépliant tes longues jambes.",p:-1},{l:"Téter",r:"Le lait est riche.",s:1}]},
 {d:1500,x:"Tu marches avec le troupeau, de puits en puits. La famille de pasteurs vit de ton lait.",
  e:"Une enfant somalienne, qui te trait le matin : elle connaît ton nom.",
  f:"Un dromadaire peut rester plus d'une semaine sans boire et boire plus de 100 litres en quelques minutes.",
  c:[{l:"Suivre le chef de troupeau",r:"Vous trouvez de l'eau au bout de six jours.",s:-1},{l:"Brouter les épineux",r:"Ta bouche est faite pour ça.",s:1}]},
 {d:3000,x:"La sécheresse dure depuis trois saisons. Les puits se tarissent. Autour de vous, des carcasses de chèvres.",
  e:"Un climatologue : « Cinq saisons des pluies ratées d'affilée. Du jamais vu. »",
  f:"Entre 2020 et 2023, la pire sécheresse depuis des décennies dans la Corne de l'Afrique a tué des millions de têtes de bétail.",
  c:[{l:"Marcher vers le sud",r:"La famille te suit. Il faut dix jours.",s:-2,risk:{p:.2,t:"Tu t'agenouilles dans le sable et tu ne te relèves pas."}},{l:"Rester au campement",r:"La famille partage son eau avec toi.",s:-2}]},
 {d:3200,end:1,sc:{bg:"desert",n:2,who:"chameau",extra:"humain"},x:"Pour nourrir les enfants, la famille te vend au marché.",
  e:"Un marchand saoudien, qui achète des dromadaires par centaines.",
  f:"La Somalie exporte chaque année des dizaines de milliers de dromadaires vivants vers la péninsule Arabique."}
 ]});
